<script setup>import{Head,router}from'@inertiajs/vue3';import AppLayout from'../../../Layouts/AppLayout.vue';import PageBanner from'../../../Components/PageBanner.vue';defineOptions({layout:AppLayout});const props=defineProps({shift:Object,summary:Object,snapshots:Array});const close=()=>router.post(`/monitoring/shifts/${props.shift.id}/close`,{}, {preserveScroll:true});const qty=v=>Number(v||0).toLocaleString('id-ID',{maximumFractionDigits:0});</script>
<template><Head title="Detail Rekap Shift"/><div class="units-page"><PageBanner :title="`Rekap ${shift.shift_code}`" :description="`${shift.starts_at} sampai ${shift.ends_at}`" icon="layers"/><section class="summary-grid"><article v-for="(value,key) in {Awal:summary.opening,Masuk:summary.in,Keluar:summary.out,Penyesuaian:summary.adjustment,Akhir:summary.closing}" :key="key" class="summary-card"><span>{{key}}</span><strong>{{qty(value)}}</strong></article></section><section class="surface-card"><div class="section-heading"><div><h2>Kontrol shift</h2><p>{{summary.transaction_ids.length}} transaksi · {{summary.outstanding_refills}} refill outstanding · {{summary.outstanding_documents}} dokumen outstanding</p></div><button v-if="shift.status!=='CLOSED'" class="button button--primary" @click="close">Tutup dan bekukan shift</button></div><p v-if="summary.late_postings.length" class="field-error">Ada {{summary.late_postings.length}} transaksi late posting.</p><h3>Versi snapshot</h3><ul><li v-for="snapshot in snapshots" :key="snapshot.id">Versi {{snapshot.version}} · checksum {{snapshot.checksum}}</li></ul></section></div></template>
